.ruler-top h3{font-size:16px}.ruler-top .hint{color:var(--muted);font-size:13px}
.rl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
.rl-col{border:1px solid var(--line);border-radius:10px;background:#fff;display:flex;flex-direction:column;min-width:0;border-top:4px solid var(--c)}
.rl-h{display:flex;align-items:center;gap:10px;padding:12px 14px 10px;background:var(--cl);border-bottom:1px solid var(--line2)}
.rl-h b{font-size:26px;line-height:1;color:var(--c);font-weight:800;min-width:30px}.rl-h span{font-weight:700;font-size:14px;color:var(--ink)}.rl-h small{display:block;font-weight:500;color:var(--muted);font-size:11.5px}
.rl-list{list-style:none;margin:0;padding:6px;display:flex;flex-direction:column;gap:4px;flex:1}
.rl-it{display:grid;grid-template-columns:1fr auto;gap:1px 8px;align-items:center;padding:7px 9px;border-radius:7px;cursor:pointer;border:1px solid transparent;background:none;text-align:right;width:100%;font:inherit;color:inherit}
.rl-it:hover,.rl-it:focus-visible{background:var(--cl);border-color:var(--line2)}
.rl-it .t{font-weight:600;font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rl-it .s{grid-column:1;font-size:11.5px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.rl-it .d{grid-row:1/3;grid-column:2;font-size:12px;font-weight:700;color:var(--c);background:var(--cl);border-radius:999px;padding:3px 9px;white-space:nowrap}
.rl-empty{color:var(--muted);font-size:12.5px;padding:14px 10px;text-align:center}
.rl-more{margin:0 6px 8px;border:1px dashed var(--line);background:none;border-radius:7px;padding:6px;font:inherit;font-size:12.5px;font-weight:600;color:var(--c);cursor:pointer}.rl-more:hover{background:var(--cl)}
.rl-sum{display:flex;gap:6px;flex-wrap:wrap}.rl-sum span{font-size:12.5px;font-weight:700;border-radius:999px;padding:4px 11px;background:var(--cl);color:var(--c)}
@media (max-width:1100px){.rl{grid-template-columns:repeat(2,minmax(0,1fr))}}@media (max-width:620px){.rl{grid-template-columns:1fr}}
.track{position:relative;height:96px;margin:0 6px}
